  __ovr_C_lon__initial = pop!(__overrides, "C_lon__initial", nothing); isnothing(__ovr_C_lon__initial) || (__initial_conditions[C_lon] = __ovr_C_lon__initial)
  __ovr_C_lat = pop!(__overrides, "C_lat", nothing); isnothing(__ovr_C_lat) || push!(__eqs, C_lat ~ __ovr_C_lat)
  __ovr_C_lat__initial = pop!(__overrides, "C_lat__initial", nothing); isnothing(__ovr_C_lat__initial) || (__initial_conditions[C_lat] = __ovr_C_lat__initial)
  __ovr_Udot = pop!(__overrides, "Udot", nothing); isnothing(__ovr_Udot) || push!(__eqs, Udot ~ __ovr_Udot)
  __ovr_Udot__initial = pop!(__overrides, "Udot__initial", nothing); isnothing(__ovr_Udot__initial) || (__initial_conditions[Udot] = __ovr_Udot__initial)
  __ovr_Vdot = pop!(__overrides, "Vdot", nothing); isnothing(__ovr_Vdot) || push!(__eqs, Vdot ~ __ovr_Vdot)
  __ovr_Vdot__initial = pop!(__overrides, "Vdot__initial", nothing); isnothing(__ovr_Vdot__initial) || (__initial_conditions[Vdot] = __ovr_Vdot__initial)
  __ovr_Wdot = pop!(__overrides, "Wdot", nothing); isnothing(__ovr_Wdot) || push!(__eqs, Wdot ~ __ovr_Wdot)
  __ovr_Wdot__initial = pop!(__overrides, "Wdot__initial", nothing); isnothing(__ovr_Wdot__initial) || (__initial_conditions[Wdot] = __ovr_Wdot__initial)
  __ovr_L_tot = pop!(__overrides, "L_tot", nothing); isnothing(__ovr_L_tot) || push!(__eqs, L_tot ~ __ovr_L_tot)
  __ovr_L_tot__initial = pop!(__overrides, "L_tot__initial", nothing); isnothing(__ovr_L_tot__initial) || (__initial_conditions[L_tot] = __ovr_L_tot__initial)
  __ovr_M_tot = pop!(__overrides, "M_tot", nothing); isnothing(__ovr_M_tot) || push!(__eqs, M_tot ~ __ovr_M_tot)
  __ovr_M_tot__initial = pop!(__overrides, "M_tot__initial", nothing); isnothing(__ovr_M_tot__initial) || (__initial_conditions[M_tot] = __ovr_M_tot__initial)
  __ovr_N_tot = pop!(__overrides, "N_tot", nothing); isnothing(__ovr_N_tot) || push!(__eqs, N_tot ~ __ovr_N_tot)
  __ovr_N_tot__initial = pop!(__overrides, "N_tot__initial", nothing); isnothing(__ovr_N_tot__initial) || (__initial_conditions[N_tot] = __ovr_N_tot__initial)
  __ovr_denom = pop!(__overrides, "denom", nothing); isnothing(__ovr_denom) || push!(__eqs, denom ~ __ovr_denom)
  __ovr_denom__initial = pop!(__overrides, "denom__initial", nothing); isnothing(__ovr_denom__initial) || (__initial_conditions[denom] = __ovr_denom__initial)

  ### Constants
  __constants = Any[]

  ### Components

  ### Check there are no unmatched overrides
  isempty(__overrides) || throw(ArgumentError("overrides: [$(join(keys(__overrides), ", "))] don't match names found in model. These names may exist in the model but could have been conditionally excluded."))

  ### Guesses

  ### Initialization Equations
  push!(__initialization_eqs, alt ~ alt_init)
  push!(__initialization_eqs, phi ~ phi_init)
  push!(__initialization_eqs, theta ~ theta_init)
  push!(__initialization_eqs, psi ~ psi_init)
  push!(__initialization_eqs, vt ~ vt_init)
  push!(__initialization_eqs, alpha ~ alpha_init)
  push!(__initialization_eqs, beta ~ beta_init)
  push!(__initialization_eqs, P ~ P_init)
  push!(__initialization_eqs, Q ~ Q_init)
  push!(__initialization_eqs, R ~ R_init)

  ### Assertions
  __assertions = []

  ### Equations
  push!(__eqs, T ~ u_in[1])
  push!(__eqs, el ~ u_in[2])
  push!(__eqs, ail ~ u_in[3])
  push!(__eqs, rud ~ u_in[4])
  push!(__eqs, lef ~ u_in[5])
  push!(__eqs, y_out[1] ~ npos)
  push!(__eqs, y_out[2] ~ epos)
  push!(__eqs, y_out[3] ~ alt)
  push!(__eqs, y_out[4] ~ phi)
  push!(__eqs, y_out[5] ~ theta)
  push!(__eqs, y_out[6] ~ psi)
  push!(__eqs, y_out[7] ~ vt)
  push!(__eqs, y_out[8] ~ alpha)
  push!(__eqs, y_out[9] ~ beta)
  push!(__eqs, y_out[10] ~ P)
  push!(__eqs, y_out[11] ~ Q)
  push!(__eqs, y_out[12] ~ R)
  push!(__eqs, el_rad ~ el * deg2rad)
  push!(__eqs, ail_rad ~ ail * deg2rad)
  push!(__eqs, rud_rad ~ rud * deg2rad)
  push!(__eqs, lef_rad ~ lef * deg2rad)
  push!(__eqs, sa ~ sin(alpha))
  push!(__eqs, ca ~ cos(alpha))
  push!(__eqs, sb ~ sin(beta))
  push!(__eqs, cb ~ cos(beta))
  push!(__eqs, st ~ sin(theta))
  push!(__eqs, ct ~ cos(theta))
  push!(__eqs, tt ~ tan(theta))
  push!(__eqs, sphi ~ sin(phi))
  push!(__eqs, cphi ~ cos(phi))
  push!(__eqs, spsi ~ sin(psi))
  push!(__eqs, cpsi ~ cos(psi))
  push!(__eqs, U ~ vt * ca * cb)
  push!(__eqs, V_body ~ vt * sb)
  push!(__eqs, W ~ vt * sa * cb)
  push!(__eqs, rho ~ 1.225 * (1.0 - 0.0065 * alt / 288.15) ^ 4.256)
  push!(__eqs, qbar ~ 0.5 * rho * vt * vt)
  push!(__eqs, x_lon[1] ~ alpha)
  push!(__eqs, x_lon[2] ~ alpha * alpha)
  push!(__eqs, x_lon[3] ~ el_rad)
  push!(__eqs, x_lon[4] ~ cbar * Q / (2.0 * vt))
  push!(__eqs, x_lat[1] ~ beta)
  push!(__eqs, x_lat[2] ~ ail_rad)
  push!(__eqs, x_lat[3] ~ rud_rad)
  push!(__eqs, x_lat[4] ~ B * P / (2.0 * vt))
  push!(__eqs, x_lat[5] ~ B * R / (2.0 * vt))
  push!(__eqs, C_lon ~ C0_lon + Cmat_lon * x_lon)
  push!(__eqs, C_lat ~ C0_lat + Cmat_lat * x_lat)
  push!(__eqs, Udot ~ R * V_body - Q * W - g * st + qbar * S * C_lon[1] / m + T / m)
  push!(__eqs, Vdot ~ P * W - R * U + g * ct * sphi + qbar * S * C_lat[1] / m)
  push!(__eqs, Wdot ~ Q * U - P * V_body + g * ct * cphi + qbar * S * C_lon[2] / m)
  push!(__eqs, ModelingToolkit.D_nounits(vt) ~ (U * Udot + V_body * Vdot + W * Wdot) / vt)
  push!(__eqs, ModelingToolkit.D_nounits(alpha) ~ (U * Wdot - W * Udot) / (U * U + W * W))
  push!(__eqs, ModelingToolkit.D_nounits(beta) ~ (Vdot * vt - V_body * (U * Udot + V_body * Vdot + W * Wdot) / vt) / (vt * vt * cb))
  push!(__eqs, L_tot ~ C_lat[2] * qbar * S * B)
  push!(__eqs, M_tot ~ C_lon[3] * qbar * S * cbar)
  push!(__eqs, N_tot ~ C_lat[3] * qbar * S * B)
  push!(__eqs, denom ~ Jx * Jz - Jxz * Jxz)
  push!(__eqs, ModelingToolkit.D_nounits(P) ~ (Jz * L_tot + Jxz * N_tot - (Jz * (Jz - Jy) + Jxz * Jxz) * Q * R + Jxz * (Jx - Jy + Jz) * P * Q + Jxz * Q * Heng) / denom)
  push!(__eqs, ModelingToolkit.D_nounits(Q) ~ (M_tot + (Jz - Jx) * P * R - Jxz * (P * P - R * R) - R * Heng) / Jy)
  push!(__eqs, ModelingToolkit.D_nounits(R) ~ (Jx * N_tot + Jxz * L_tot + (Jx * (Jx - Jy) + Jxz * Jxz) * P * Q - Jxz * (Jx - Jy + Jz) * Q * R + Jx * Q * Heng) / denom)
  push!(__eqs, ModelingToolkit.D_nounits(npos) ~ U * ct * cpsi + V_body * (sphi * st * cpsi - cphi * spsi) + W * (cphi * st * cpsi + sphi * spsi))
  push!(__eqs, ModelingToolkit.D_nounits(epos) ~ U * ct * spsi + V_body * (sphi * st * spsi + cphi * cpsi) + W * (cphi * st * spsi - sphi * cpsi))
  push!(__eqs, ModelingToolkit.D_nounits(alt) ~ U * st - V_body * sphi * ct - W * cphi * ct)
  push!(__eqs, ModelingToolkit.D_nounits(phi) ~ P + tt * (Q * sphi + R * cphi))
  push!(__eqs, ModelingToolkit.D_nounits(theta) ~ Q * cphi - R * sphi)
  push!(__eqs, ModelingToolkit.D_nounits(psi) ~ (Q * sphi + R * cphi) / ct)

  # Return completely constructed System
  return System(__eqs, t, __vars, __params; systems=__systems, initial_conditions=__initial_conditions, guesses=__guesses, name, initialization_eqs=__initialization_eqs, bindings=__bindings, assertions=__assertions)
end
export F16PlantModel
